static void TFModelDiscoveryError(UIViewController *controller,NSError *error){
 NSDictionary *details=[error.userInfo[@"diagnostics"] isKindOfClass:NSDictionary.class]?error.userInfo[@"diagnostics"]:@{};
 NSMutableDictionary *report=[details mutableCopy];report[@"operation"]=@"获取模型列表";report[@"errorDomain"]=error.domain?:@"";report[@"errorCode"]=@(error.code);report[@"appVersion"]=[NSBundle.mainBundle objectForInfoDictionaryKey:@"CFBundleShortVersionString"]?:@"";report[@"appBuild"]=[NSBundle.mainBundle objectForInfoDictionaryKey:@"CFBundleVersion"]?:@"";
 NSString *reason=error.localizedDescription;NSString *message=reason.length&&reason.length<=120?reason:@"请求失败，请复制诊断查看详细原因。";
 UIAlertController *alert=[UIAlertController alertControllerWithTitle:@"获取模型失败" message:message preferredStyle:UIAlertControllerStyleAlert];
 [alert addAction:[UIAlertAction actionWithTitle:@"复制诊断" style:UIAlertActionStyleDefault handler:^(UIAlertAction *action){NSData *data=[NSJSONSerialization dataWithJSONObject:report options:NSJSONWritingPrettyPrinted|NSJSONWritingSortedKeys error:nil];UIPasteboard.generalPasteboard.string=data?[[NSString alloc]initWithData:data encoding:NSUTF8StringEncoding]:@"诊断生成失败";}]];
 [alert addAction:[UIAlertAction actionWithTitle:@"好" style:UIAlertActionStyleCancel handler:nil]];[controller presentViewController:alert animated:YES completion:nil];
}
static NSString *TFProtocolTitle(NSString *identifier){for(NSDictionary *entry in TFAIProtocolCatalog())if([entry[@"id"] isEqual:identifier])return entry[@"name"];return identifier?:@"选择服务协议";}
@implementation TFAIFieldSheet
- (void)viewDidLoad {
 [super viewDidLoad];self.view.backgroundColor=UIColor.systemGroupedBackgroundColor;
 self.navigationItem.rightBarButtonItem=AIBar(@"checkmark",@"确认",self,@selector(submit));self.navigationItem.leftBarButtonItem=AIBar(@"xmark",@"取消",self,@selector(close));
 UILabel *label=[UILabel new];label.text=self.hint;label.numberOfLines=0;label.textColor=UIColor.secondaryLabelColor;label.font=[UIFont preferredFontForTextStyle:UIFontTextStyleFootnote];label.translatesAutoresizingMaskIntoConstraints=NO;[self.view addSubview:label];
 self.text=[UITextView new];self.text.text=self.value;self.text.font=[UIFont preferredFontForTextStyle:UIFontTextStyleBody];self.text.backgroundColor=UIColor.secondarySystemGroupedBackgroundColor;self.text.layer.cornerRadius=14;self.text.textContainerInset=UIEdgeInsetsMake(14,12,14,12);self.text.secureTextEntry=self.secure;self.text.autocapitalizationType=UITextAutocapitalizationTypeNone;self.text.autocorrectionType=UITextAutocorrectionTypeNo;self.text.translatesAutoresizingMaskIntoConstraints=NO;[self.view addSubview:self.text];
 [NSLayoutConstraint activateConstraints:@[[label.topAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.topAnchor constant:16],[label.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor constant:20],[label.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor constant:-20],[self.text.topAnchor constraintEqualToAnchor:label.bottomAnchor constant:12],[self.text.leadingAnchor constraintEqualToAnchor:label.leadingAnchor],[self.text.trailingAnchor constraintEqualToAnchor:label.trailingAnchor],[self.text.heightAnchor constraintEqualToConstant:100]]];
 UITapGestureRecognizer *tap=[[UITapGestureRecognizer alloc]initWithTarget:self action:@selector(hideKeyboard)];tap.cancelsTouchesInView=NO;[self.view addGestureRecognizer:tap];
}
- (void)hideKeyboard{[self.view endEditing:YES];}
- (void)submit{NSString *v=[self.text.text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];void(^save)(NSString *)=self.save;[self dismissViewControllerAnimated:YES completion:^{if(save)save(v);}];}
- (void)close{[self dismissViewControllerAnimated:YES completion:nil];}
@end
static void EditField(UIViewController *host,NSString *title,NSString *value,NSString *hint,BOOL secure,void(^save)(NSString *)) {
 TFAIFieldSheet *f=[TFAIFieldSheet new];f.title=title;f.value=value;f.hint=hint;f.secure=secure;f.save=save;TMCNavigationController *nav=[[TMCNavigationController alloc]initWithRootViewController:f];nav.modalPresentationStyle=UIModalPresentationPageSheet;nav.sheetPresentationController.detents=@[UISheetPresentationControllerDetent.mediumDetent,UISheetPresentationControllerDetent.largeDetent];nav.sheetPresentationController.prefersGrabberVisible=YES;[host presentViewController:nav animated:YES completion:nil];
