- (void)lanHTTPToggle:(UISwitch *)sender{[self changeHTTP:sender localOnly:YES];}
- (void)httpToggle:(UISwitch *)sender{[self changeHTTP:sender localOnly:NO];}
- (void)changeHTTP:(UISwitch *)sender localOnly:(BOOL)lan{
 NSString *key=lan?@"allowLANHTTP":@"allowHTTP";
 if(!sender.on){self.connection[key]=@NO;[self persist:nil];return;}
 sender.on=NO;UIAlertController *a=[UIAlertController alertControllerWithTitle:lan?@"仅允许局域网 HTTP？":@"允许任意主机 HTTP？" message:lan?@"HTTP 不加密，请求、附件及凭据以明文传输。仅用于可信局域网；公网 HTTP 仍被阻止。":@"这将允许公网及局域网 HTTP，模型请求和 API 密钥可能被截获。仅在明确需要时启用。" preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"启用此连接" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){self.connection[key]=@YES;self.connection[lan?@"allowHTTP":@"allowLANHTTP"]=@NO;[self persist:nil];}]];[self presentViewController:a animated:YES completion:nil];
}
- (void)editCustomHeaders{
 NSError *error=nil;NSDictionary *headers=[TFAIConnections customHeaders:self.connection[@"id"] error:&error];if(!headers){AIAlert(self,@"无法读取请求头",error.localizedDescription);return;}
 NSString *json=[[NSString alloc]initWithData:[NSJSONSerialization dataWithJSONObject:headers options:NSJSONWritingPrettyPrinted|NSJSONWritingSortedKeys error:nil] encoding:NSUTF8StringEncoding];
 __weak typeof(self) weak=self;EditField(self,@"自定义 HTTP Headers",json,@"填写 JSON 对象，例如 {\"X-Client-Name\":\"my-client\"}。值只存钥匙串，不向模型提供。Authorization 会覆盖默认 API 密钥鉴权；User-Agent 使用专用入口。填 {} 清除。",NO,^(NSString *value){NSError *e=nil;id raw=[NSJSONSerialization JSONObjectWithData:[(value.length?value:@"{}") dataUsingEncoding:NSUTF8StringEncoding] options:NSJSONReadingFragmentsAllowed error:nil];NSDictionary *validated=raw?TFAIValidatedCustomHeaders(raw,&e):nil;if(!validated){AIAlert(weak,@"请求头未保存",e.localizedDescription?:@"请输入有效的 JSON 对象，所有值须为单行字符串。");return;}weak.connection[@"customHeaders"]=validated;[weak persist:nil];});
}
- (void)toolToggle:(UISwitch *)sender{self.connection[@"toolsEnabled"]=@(sender.on);[self persist:nil];}
- (void)persist:(NSString *)secret {
