}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i {if(i.section==4){[t deselectRowAtIndexPath:i animated:YES];if(i.row==0){[self.navigationController pushViewController:TFAIBalanceController(self.connection) animated:YES];return;}if(i.row==2)return;UIAlertController *menu=[UIAlertController alertControllerWithTitle:@"余额接口" message:@"默认自动识别官方接口或当前 API 同源的 Sub2API 钱包，无需另填地址。不支持的钱包不会显示为余额 0。" preferredStyle:UIAlertControllerStyleActionSheet];NSArray *keys=@[@"auto",@"off",@"sub2api"],*names=@[@"自动识别（官方 / 同源钱包）",@"不查询",@"Sub2API 钱包"];for(NSUInteger n=0;n<keys.count;n++)[menu addAction:[UIAlertAction actionWithTitle:names[n] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action){self.connection[@"balanceAdapter"]=keys[n];[self persist:nil];}]];[menu addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];menu.popoverPresentationController.sourceView=[t cellForRowAtIndexPath:i];[self presentViewController:menu animated:YES completion:nil];return;}
 [t deselectRowAtIndexPath:i animated:YES];if(self.busy||(i.section==0&&i.row==5))return;__weak typeof(self) weak=self;if(i.section==3){if(i.row==1){[self editCustomHeaders];return;}if(i.row==0)EditField(self,@"自订 User-Agent",self.connection[@"userAgent"],@"填写单行 ASCII 文本，最多 512 字符，例如 MyClient/1.0。留空恢复系统默认。",NO,^(NSString *value){weak.connection[@"userAgent"]=value;[weak persist:nil];});return;}
