@interface TFAISettings : UITableViewController
@property NSString *projectID;
@property NSArray *connections;
@property NSMutableDictionary *balances;
@end
@implementation TFAISettings
- (BOOL)tableView:(UITableView *)tableView canEditRowAtIndexPath:(NSIndexPath *)indexPath{return indexPath.section==1&&indexPath.row<self.connections.count;}
- (void)removeConnectionWithID:(NSString *)identifier{[TFAIConnections remove:identifier];self.connections=TFAIConnections.all;[self.tableView reloadData];}
- (void)confirmDeleteConnection:(NSDictionary *)connection{UIAlertController *alert=[UIAlertController alertControllerWithTitle:[NSString stringWithFormat:@"删除连接“%@”？",connection[@"name"]?:@"未命名"] message:@"同时删除此连接保存的 API 密钥；引用它的项目需要重新选择连接。会话和项目文件会保留。" preferredStyle:UIAlertControllerStyleAlert];[alert addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[alert addAction:[UIAlertAction actionWithTitle:@"删除" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *action){[self removeConnectionWithID:connection[@"id"]];}]];[self presentViewController:alert animated:YES completion:nil];}
- (UISwipeActionsConfiguration *)tableView:(UITableView *)tableView trailingSwipeActionsConfigurationForRowAtIndexPath:(NSIndexPath *)indexPath{if(![self tableView:tableView canEditRowAtIndexPath:indexPath])return nil;NSDictionary *connection=self.connections[indexPath.row];UIContextualAction *remove=[UIContextualAction contextualActionWithStyle:UIContextualActionStyleDestructive title:@"删除" handler:^(UIContextualAction *action,UIView *source,void(^finished)(BOOL)){finished(YES);[self confirmDeleteConnection:connection];}];remove.image=[UIImage systemImageNamed:@"trash"];UIContextualAction *edit=[UIContextualAction contextualActionWithStyle:UIContextualActionStyleNormal title:@"编辑" handler:^(UIContextualAction *action,UIView *source,void(^finished)(BOOL)){finished(YES);TFAIConnectionEditor *editor=[[TFAIConnectionEditor alloc]initWithStyle:UITableViewStyleInsetGrouped];editor.connection=[connection mutableCopy];[self.navigationController pushViewController:editor animated:YES];}];edit.image=[UIImage systemImageNamed:@"pencil"];edit.backgroundColor=UIColor.systemOrangeColor;UISwipeActionsConfiguration *config=[UISwipeActionsConfiguration configurationWithActions:@[remove,edit]];config.performsFirstActionWithFullSwipe=NO;return config;}
- (void)viewDidLoad{[super viewDidLoad];self.title=self.projectID?@"项目 AI 连接":@"AI 模型与连接";self.navigationItem.rightBarButtonItem=AIBar(@"plus",@"添加连接",self,@selector(addConnection));}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];self.connections=TFAIConnections.all;if(!self.balances)self.balances=[NSMutableDictionary new];[self.tableView reloadData];__weak typeof(self) weak=self;for(NSDictionary *c in self.connections)if(TFAIBalanceAdapter(c))[[TFAIProviderBalance shared] fetch:c refresh:NO completion:^(NSDictionary *r){weak.balances[c[@"id"]]=r;[weak.tableView reloadData];}];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)t{return 5;}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return s==4?3:s==3?1:s==2?2:s==1?MAX(1,self.connections.count):1;}
- (NSString *)tableView:(UITableView *)t titleForHeaderInSection:(NSInteger)s{return @[@"当前生效",@"服务连接",@"工具能力",@"后台执行",@"用量与账户"][s];}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{if(s==4)return @"用量记录保存在本机。余额由服务商返回，可能是账户钱包或 Key 剩余额度，未报告的数据不会显示为 0。";if(s==3)return @"有 AI 任务时播放静音音频辅助后台执行，完成或停止后自动关闭。可与其他音频混播；会增加耗电，来电或系统资源限制仍可能中断。关闭后使用系统提供的后台时间。";if(s==2)return @"网页与 GitHub 查询为只读操作，搜索和认证独立配置。";return s==0?(self.projectID?@"项目默认继承全局连接。点击服务可为此项目选择；点击当前生效可恢复继承。":@"连接可由全部项目共享；每个项目也能单独选择。"):@"点击连接选择默认或编辑。AI 对话需要联网；源码修改、编译与 Git 操作由本机工具执行。未填写模型与密钥前不会发送请求。";}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i {if(i.section==4&&i.row==2){UITableViewCell *c=AICell(@"上下文保护大小",[NSString stringWithFormat:@"%lu KiB · 全局生效",(unsigned long)TFAIContextProjection.budgetKiB],@"text.alignleft");c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}if(i.section==4){UITableViewCell *c=AICell(i.row==0?@"用量统计":@"服务商余额",i.row==0?@"日期 · 会话 · 模型 · 缓存命中":@"账户余额与 Key 剩余额度",i.row==0?@"chart.bar.xaxis":@"creditcard");c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}if(i.section==3){UITableViewCell *c=AICell(@"音频辅助后台运行",@"仅在 AI 任务期间启用",@"waveform");UISwitch *toggle=[UISwitch new];toggle.on=TFAIAudioBackgroundEnabled();[toggle addTarget:self action:@selector(audioBackgroundChanged:) forControlEvents:UIControlEventValueChanged];c.accessoryView=toggle;c.selectionStyle=UITableViewCellSelectionStyleNone;return c;}if(i.section==2&&i.row==1){UITableViewCell *c=AICell(@"通用 Agent",@"技能 · MCP · 只读网页 · 构建任务",@"square.stack.3d.up");c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}if(i.section==2){UITableViewCell *c=AICell(@"联网检索",@"网页 · 搜索 · GitHub",@"globe");c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}NSDictionary *effective=[TFAIConnections effectiveForProject:self.projectID];if(i.section==0){UITableViewCell *c=AICell(effective[@"name"]?:@"尚未选择连接",[NSString stringWithFormat:@"%@ · %@\n%@",[effective[@"source"] isEqual:@"project"]?@"项目覆盖":@"继承全局",effective[@"model"]?:@"请选择模型",effective[@"baseURL"]?:@"点击 + 添加服务"],@"checkmark.circle");return c;}if(!self.connections.count)return AICell(@"添加第一个连接",@"支持 OpenAI、Anthropic、DeepSeek、Gemini 等服务",@"plus.circle");NSDictionary *connection=self.connections[i.row];UITableViewCell *c=AICell(connection[@"name"],TFAIBalanceAdapter(connection)?[NSString stringWithFormat:@"%@\n%@",connection[@"model"]?:@"尚未选择模型",TFAIBalanceCaption(self.balances[connection[@"id"]])]:connection[@"model"]?:@"尚未选择模型",@"network");c.accessoryType=[connection[@"id"] isEqual:effective[@"id"]]?UITableViewCellAccessoryCheckmark:UITableViewCellAccessoryDisclosureIndicator;return c;}
- (void)customContextBudget {
 UIAlertController *a=[UIAlertController alertControllerWithTitle:@"自定义上下文保护大小" message:@"单位 KiB，范围 64–16384（16 MiB）。这是发送文本 JSON 的本机保护预算，不是模型 tokens 上限。" preferredStyle:UIAlertControllerStyleAlert];
 [a addTextFieldWithConfigurationHandler:^(UITextField *field){field.keyboardType=UIKeyboardTypeNumberPad;field.text=[NSString stringWithFormat:@"%lu",(unsigned long)TFAIContextProjection.budgetKiB];field.placeholder=@"例如 512";field.accessibilityLabel=@"上下文保护大小 KiB";}];
 [a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];
 [a addAction:[UIAlertAction actionWithTitle:@"保存" style:UIAlertActionStyleDefault handler:^(UIAlertAction *action){NSString *text=[a.textFields.firstObject.text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];NSCharacterSet *invalid=NSCharacterSet.decimalDigitCharacterSet.invertedSet;BOOL valid=text.length>0&&text.length<=5&&[text rangeOfCharacterFromSet:invalid].location==NSNotFound;NSUInteger value=text.integerValue;if(!valid||![TFAIContextProjection setBudgetKiB:value]){AIAlert(self,@"大小无效",@"请输入 64 到 16384 之间的整数，单位 KiB。");return;}[self.tableView reloadData];}]];
 [self presentViewController:a animated:YES completion:nil];
}
- (void)contextBudgetMenu:(NSIndexPath *)index {
 UIAlertController *a=[UIAlertController alertControllerWithTitle:@"上下文保护大小" message:@"全局设置，从下一次请求生效。这是最终请求上限，旧历史会提前独立整理。调大可容纳更长输入或近期内容；服务商窗口限制仍生效。默认 256 KiB。" preferredStyle:UIAlertControllerStyleActionSheet];
 for(NSNumber *value in @[@128,@256,@512,@1024,@2048,@4096]){NSString *title=[NSString stringWithFormat:@"%@ KiB%@%@",value,value.unsignedIntegerValue==256?@"（默认）":@"",value.unsignedIntegerValue==TFAIContextProjection.budgetKiB?@" ✓":@""];[a addAction:[UIAlertAction actionWithTitle:title style:UIAlertActionStyleDefault handler:^(UIAlertAction *action){[TFAIContextProjection setBudgetKiB:value.unsignedIntegerValue];[self.tableView reloadData];}]];}
 [a addAction:[UIAlertAction actionWithTitle:@"自定义…" style:UIAlertActionStyleDefault handler:^(UIAlertAction *action){[self customContextBudget];}]];
 [a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.sourceView=[self.tableView cellForRowAtIndexPath:index];a.popoverPresentationController.sourceRect=[self.tableView cellForRowAtIndexPath:index].bounds;[self presentViewController:a animated:YES completion:nil];
}
- (void)audioBackgroundChanged:(UISwitch *)sender{TFAIBackgroundSetAudioEnabled(sender.on);}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i {if(i.section==4&&i.row==2){[t deselectRowAtIndexPath:i animated:YES];[self contextBudgetMenu:i];return;}if(i.section==4){[t deselectRowAtIndexPath:i animated:YES];[self.navigationController pushViewController:i.row==0?TFAIUsageController(self.projectID,nil):TFAIBalanceController(nil) animated:YES];return;}
 if(i.section==3){[t deselectRowAtIndexPath:i animated:YES];return;}
 [t deselectRowAtIndexPath:i animated:YES];if(i.section==2&&i.row==1){[self.navigationController pushViewController:TFAIAgentSettingsController(nil,nil) animated:YES];return;}if(i.section==2){[self.navigationController pushViewController:TFAIWebSettingsController() animated:YES];return;}if(i.section==0){if(self.projectID){[TFAIConnections setConnection:nil project:self.projectID];[t reloadData];}return;}if(!self.connections.count){[self addConnection];return;}
 NSDictionary *c=self.connections[i.row];UIAlertController *a=[UIAlertController alertControllerWithTitle:c[@"name"] message:c[@"baseURL"] preferredStyle:UIAlertControllerStyleActionSheet];[a addAction:[UIAlertAction actionWithTitle:self.projectID?@"用于此项目":@"设为全局默认" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[TFAIConnections setConnection:c[@"id"] project:self.projectID];[t reloadData];}]];[a addAction:[UIAlertAction actionWithTitle:@"编辑连接与测试" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){TFAIConnectionEditor *v=[[TFAIConnectionEditor alloc]initWithStyle:UITableViewStyleInsetGrouped];v.connection=[c mutableCopy];[self.navigationController pushViewController:v animated:YES];}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.sourceView=[t cellForRowAtIndexPath:i];[self presentViewController:a animated:YES completion:nil];
}
- (void)createProvider:(NSDictionary *)entry base:(NSString *)base{NSMutableDictionary *c=[@{@"id":NSUUID.UUID.UUIDString,@"name":entry[@"name"],@"protocol":entry[@"id"],@"baseURL":base,@"model":([entry[@"id"] isEqualToString:@"opencode-go"]?@"glm-5.3-flash":@""),@"models":@[],@"authMethod":@"apiKey"} mutableCopy];NSError *e=nil;if(![TFAIConnections save:c secret:nil error:&e]){AIAlert(self,@"添加失败",e.localizedDescription);return;}TFAIConnectionEditor *v=[[TFAIConnectionEditor alloc]initWithStyle:UITableViewStyleInsetGrouped];v.connection=c;[self.navigationController pushViewController:v animated:YES];}
- (void)addConnection{UIAlertController *menu=[UIAlertController alertControllerWithTitle:@"添加服务商" message:@"选择官方预设或自定义兼容API；能力均以当前连接实测为准。" preferredStyle:UIAlertControllerStyleActionSheet];for(NSDictionary *entry in TFAIProviderRegistry())[menu addAction:[UIAlertAction actionWithTitle:entry[@"name"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){if([entry[@"id"] isEqual:@"custom"])EditField(self,@"自定义 OpenAI 兼容服务",@"",@"填写HTTPS API前缀，例如你的服务商文档给出的/v1地址。",NO,^(NSString *url){[self createProvider:entry base:url];});else[self createProvider:entry base:entry[@"baseURL"]];}]];[menu addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];menu.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItem;[self presentViewController:menu animated:YES completion:nil];}
@end
UIViewController *TFAISettingsController(NSString *projectID){TFAISettings *v=[[TFAISettings alloc]initWithStyle:UITableViewStyleInsetGrouped];v.projectID=projectID;return v;}
